#define PI 3.14159265359
#define NUM_PARTICLES 2
#define PIXELIZATION_FACTOR iDate.z
#define COLOR_LEVELS (iDate.z*2.0)
#define GRID_FACTOR iDate.b/40.
//(int(iDate.b+iDate.x)%2==1? 14141.9 : 0.2)

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 resolution = iResolution.xy;
    float gridSize = clamp(
        resolution.     y / PIXELIZATION_FACTOR, 
        PIXELIZATION_FACTOR, 
        1000.0 / PIXELIZATION_FACTOR
    );

    vec2 cell = floor(fragCoord / gridSize);
    vec2 pixelCenter = cell * gridSize + 0.5 * gridSize;
    vec2 uv = (2.0 * pixelCenter - resolution) / resolution.y;

    float dynamicScale = 3.14 + sin(iTime * 0.21) * 0.38;
    float time = iTime * 0.54;
    vec3 color = vec3(0.0);
    float intensity = 0.0;
float ddist = 0.0;
    for (int i = 0; i < NUM_PARTICLES; i++) {
        float id = float(i) / float(NUM_PARTICLES);
        float particleTime = (sin(iTime) + 1.0) / 2.0 * id / 30.0;
        float theta = fract(id + particleTime * 0.09) * 20.0 * dynamicScale;
        float phi = fract(id * 1.618 + particleTime * 0.015) * 2.0 * dynamicScale;

        vec3 spherePos = vec3(
            sin(phi) * cos(theta),
            sin(phi) * -sin(theta),
            cos(phi)
        );

        float angle = time * 0.468;
        mat3 rotation = mat3(
             cos(angle), 0.0, -sin(angle),
             0.0, 1.0, 0.0,
             sin(angle), 0.0, cos(angle)
        );
        spherePos = rotation * spherePos;

        vec2 screenPos = spherePos.xy / (spherePos.z + 1.4 + (sin(time) + 1.0) / 4.0);
        float dist = length(uv - screenPos);
        float glow = exp(-dist * (3.0 + float(NUM_PARTICLES) / 60.0));
		//if (dist<1.0) {
            ddist +=(abs(dist*dist*1./glow));
        //}
        intensity += glow * (0.9 + abs(sin(time / 10.0)));
        color += glow * vec3(
            0.4 + 0.6 * sin(id * PI * 2.0),
            0.3 + 0.4 * sin(time * 2.0),
            1.0
        );
    }
	ddist/=float( NUM_PARTICLES*NUM_PARTICLES);
//    ddist=ddist-.1;
    color = floor(color * COLOR_LEVELS) / COLOR_LEVELS;

    intensity = clamp(intensity,0.0,9.0);

    if (intensity < .3) {
        fragColor = vec4(vec3(.20),  (.50-ddist)*1.7);
    } else if (intensity < .38) {
        fragColor = vec4(color.rgb * vec3(exp(-intensity * 310.10)),  ((.50-ddist)*1.7));
    } else {
        fragColor = vec4(color.rgr / 0.5 * intensity, ((.50-ddist)*1.7));
    }

    if (GRID_FACTOR > 0.0) {
        float pixelWidth = min(2.50, gridSize /10.0) * gridSize / resolution.y;
        vec2 fracCoord = fract(fragCoord / gridSize);

        float gridLineX = smoothstep(pixelWidth, 0.0, fracCoord.x)
                        + smoothstep(pixelWidth, 0.0, fracCoord.y);
        gridLineX = clamp(gridLineX, 0.0, GRID_FACTOR);

        fragColor.rgb += gridLineX * mix(-fragColor.rgb, vec3(0.9), gridLineX);
    }
    fragColor = vec4(vec3(floor(fragColor.brg*COLOR_LEVELS))/COLOR_LEVELS,floor((fragColor.a*2.0-.50) * COLOR_LEVELS) / COLOR_LEVELS);
}

